120	func NewLocalScanner(opts ...ScannerOption) *LocalScanner {
121		ls := &LocalScanner{
122			fetcher: newFetcher(),
123			ctx:     context.Background(),
124			// By default, auto-update is enabled. It can be explicitly disabled
125			// by passing WithAutoUpdate(false)
126			autoUpdate: true,
127		}
128	
129		for i := range opts {
130			opts[i](ls)
131		}
132	
133		if ls.recording == nil {
134			ls.recording = recording.Null{}
135		}
136	
137		if ls.runtime == nil {
138			runtime := providers.DefaultRuntime()
139			refreshInterval := defaultRefreshInterval
140			if ls.refreshInterval > 0 {
141				refreshInterval = ls.refreshInterval
142			}
143	
144			runtime.AutoUpdate = providers.UpdateProvidersConfig{
145				Enabled:         ls.autoUpdate,
146				RefreshInterval: refreshInterval,
147			}
148			ls.runtime = runtime
149		}
150	
151		return ls
152	}
