154	func (s *LocalScanner) EnableQueue() error {
155		var err error
156		s.queue, err = newDqueClient(defaultDqueConfig, func(job *Job) {
157			// this is the handler for jobs, when they are picked up
158			ctx := mql.SetFeatures(s.ctx, mql.DefaultFeatures)
159			_, err := s.Run(ctx, job)
160			if err != nil {
161				log.Error().Err(err).Msg("could not complete the scan")
162			}
163		})
164		return err
165	}
