167	func (s *LocalScanner) Schedule(ctx context.Context, job *Job) (*Empty, error) {
168		if job == nil {
169			return nil, status.Errorf(codes.InvalidArgument, "missing scan job")
170		}
171	
172		if s.queue == nil {
173			return nil, status.Errorf(codes.Unavailable, "job queue is not available")
174		}
175	
176		s.queue.Channel() <- *job
177		return &Empty{}, nil
178	}
