 44	// Assign a policy to an asset
 45	//
 46	// We need to handle multiple cases:
 47	// 1. all local, policies and assets are available locally
 48	// 2. asset is local (via incognito mode) but policy is upstream
 49	// 3. asset and policy are upstream
 50	func (s *LocalServices) Assign(ctx context.Context, assignment *PolicyAssignment) (*Empty, error) {
 51		if len(assignment.PolicyMrns)+len(assignment.FrameworkMrns) == 0 {
 52			return nil, status.Error(codes.InvalidArgument, "a policy or framework mrn is required")
 53		}
 54	
 55		// all remote, call upstream
 56		if s.Upstream != nil && !s.Incognito {
 57			return s.Upstream.Assign(ctx, assignment)
 58		}
 59	
 60		// policies may be stored in upstream, cache them first
 61		if s.Upstream != nil && s.Incognito {
 62			// NOTE: by calling GetPolicy it is automatically cached
 63			for i := range assignment.PolicyMrns {
 64				mrn := assignment.PolicyMrns[i]
 65				_, err := s.GetPolicy(ctx, &Mrn{
 66					Mrn: mrn,
 67				})
 68				if err != nil {
 69					return nil, err
 70				}
 71			}
 72		}
 73	
 74		if err := s.DataLake.EnsureAsset(ctx, assignment.AssetMrn); err != nil {
 75			return nil, err
 76		}
 77	
 78		err := s.DataLake.MutateAssignments(ctx, &AssetMutation{
 79			AssetMrn:            assignment.AssetMrn,
 80			PolicyMrns:          assignment.PolicyMrns,
 81			FrameworkMrns:       assignment.FrameworkMrns,
 82			Action:              assignment.Action,
 83			PolicyScoringSystem: assignment.ScoringSystem,
 84		}, true)
 85		return globalEmpty, err
 86	}
 87	
 88	// Unassign a policy to an asset
 89	func (s *LocalServices) Unassign(ctx context.Context, assignment *PolicyAssignment) (*Empty, error) {
 90		if len(assignment.PolicyMrns)+len(assignment.FrameworkMrns) == 0 {
 91			return nil, status.Error(codes.InvalidArgument, "a policy or framework mrn is required")
 92		}
 93	
 94		// all remote, call upstream
 95		if s.Upstream != nil && !s.Incognito {
 96			return s.Upstream.Unassign(ctx, assignment)
 97		}
 98	
 99		err := s.DataLake.MutateAssignments(ctx, &AssetMutation{
100			AssetMrn:      assignment.AssetMrn,
101			PolicyMrns:    assignment.PolicyMrns,
102			FrameworkMrns: assignment.FrameworkMrns,
103			Action:        Action_DEACTIVATE,
104		}, true)
105		return globalEmpty, err
106	}
