108	func (s *LocalServices) SetProps(ctx context.Context, req *PropsReq) (*Empty, error) {
109		// validate that the queries compile and fill in checksums
110		conf := s.NewCompilerConfig()
111		for i := range req.Props {
112			prop := req.Props[i]
113			// set props is used for both setting and unsetting props
114			if prop.Mql == "" {
115				continue
116			}
117			code, err := prop.RefreshChecksumAndType(conf)
118			if err != nil {
119				return nil, err
120			}
121			prop.CodeId = code.CodeV2.Id
122		}
123	
124		return &Empty{}, s.DataLake.SetProps(ctx, req)
125	}
