136	// ResolveAndUpdateJobs will resolve an asset's policy and update its jobs
137	func (s *LocalServices) ResolveAndUpdateJobs(ctx context.Context, req *UpdateAssetJobsReq) (*ResolvedPolicy, error) {
138		if s.Upstream == nil || s.Incognito {
139			res, err := s.resolve(ctx, req.AssetMrn, req.AssetFilters)
140			if err != nil {
141				return nil, err
142			}
143	
144			if res.CollectorJob != nil {
145				err := res.CollectorJob.Validate()
146				if err != nil {
147					logger.FromContext(ctx).Error().
148						Err(err).
149						Msg("resolver> resolved policy is invalid")
150				}
151			}
152	
153			err = s.DataLake.SetAssetResolvedPolicy(ctx, req.AssetMrn, res, V2Code)
154			if err != nil {
155				return nil, err
156			}
157	
158			return res, nil
159		}
160	
161		res, err := s.Upstream.ResolveAndUpdateJobs(ctx, req)
162		if err != nil {
163			return nil, err
164		}
165	
166		err = s.cacheUpstreamJobs(ctx, req.AssetMrn, res)
167		if err != nil {
168			return nil, err
169		}
170	
171		return res, nil
172	}
173	
174	// UpdateAssetJobs by recalculating them
175	func (s *LocalServices) UpdateAssetJobs(ctx context.Context, req *UpdateAssetJobsReq) (*Empty, error) {
176		if s.Upstream == nil || s.Incognito {
177			return globalEmpty, s.updateAssetJobs(ctx, req.AssetMrn, req.AssetFilters)
178		}
179	
180		if _, err := s.Upstream.UpdateAssetJobs(ctx, req); err != nil {
181			return nil, err
182		}
183	
184		resolvedPolicy, err := s.Upstream.Resolve(ctx, &ResolveReq{
185			PolicyMrn:    req.AssetMrn,
186			AssetFilters: req.AssetFilters,
187		})
188		if err != nil {
189			return nil, errors.New("resolver> failed to resolve upstream jobs for caching: " + err.Error())
190		}
191	
192		return globalEmpty, s.cacheUpstreamJobs(ctx, req.AssetMrn, resolvedPolicy)
193	}
