205	// StoreResults saves the given scores and date for an asset
206	func (s *LocalServices) StoreResults(ctx context.Context, req *StoreResultsReq) (*Empty, error) {
207		logger.AddTag(ctx, "asset", req.AssetMrn)
208	
209		_, err := s.DataLake.UpdateScores(ctx, req.AssetMrn, req.Scores)
210		if err != nil {
211			return globalEmpty, err
212		}
213	
214		_, err = s.DataLake.UpdateData(ctx, req.AssetMrn, req.Data)
215		if err != nil {
216			return globalEmpty, err
217		}
218	
219		_, err = s.DataLake.UpdateRisks(ctx, req.AssetMrn, req.Risks)
220		if err != nil {
221			return globalEmpty, err
222		}
223	
224		err = s.DataLake.UpdateResources(ctx, req.AssetMrn, req.Resources)
225		if err != nil {
226			return globalEmpty, err
227		}
228	
229		if s.Upstream != nil && !s.Incognito {
230			_, err := s.Upstream.StoreResults(ctx, req)
231			if err != nil {
232				return globalEmpty, err
233			}
234		}
235	
236		return globalEmpty, nil
237	}
