279	// GetScore retrieves one score for an asset
280	func (s *LocalServices) GetScore(ctx context.Context, req *EntityScoreReq) (*Report, error) {

280		switch rtString {
281		case scan.ReportType_FULL.String():
282			reportType = scan.ReportType_FULL
283		case scan.ReportType_ERROR.String():
284			reportType = scan.ReportType_ERROR
285		case scan.ReportType_NONE.String():
286			reportType = scan.ReportType_NONE
287		}
288	
289		conf := scanConfig{
290			Features:      opts.GetFeatures(),
291			IsIncognito:   viper.GetBool("incognito"),
292			Inventory:     inv,
293			ReportType:    reportType,
294			PolicyPaths:   dedupe(viper.GetStringSlice("policy-bundle")),
295			PolicyNames:   viper.GetStringSlice("policies"),
296			RiskThreshold: riskThreshold,
297			Props:         props,
298			runtime:       runtime,
299			AgentMrn:      opts.AgentMrn,
300			OutputTarget:  viper.GetString("output-target"),
301		}
302	
303		// FIXME: DEPRECATED, remove in v12.0 and make this the default for all
304		// use-cases where we have upstream recording enabled vv
305		// Instead of depending on the feature-flag, we look at the config
306		if conf.Features.IsActive(mql.StoreResourcesData) {
307			if err = runtime.EnableResourcesRecording(); err != nil {
308				log.Fatal().Err(err).Msg("failed to enable resources recording")
309			}
310		}
311		// ^^
312	
313		// if users want to get more information on available output options,
314		// print them before executing the scan
315		output := viper.GetString("output")
316		if output == "help" {
317			fmt.Println(reporter.AllAvailableOptions())
318			os.Exit(0)
319		}
320	
321		// --json takes precedence
322		if ok := viper.GetBool("json"); ok {
323			output = "json"
324		}
325		conf.OutputFormat = output
326	
327		// detect CI/CD runs and read labels from runtime and apply them to all assets in the inventory
328		runtimeEnv := execruntime.Detect()
329		if opts.AutoDetectCICDCategory && runtimeEnv.IsAutomatedEnv() || opts.Category == "cicd" {
330			log.Info().Msg("detected ci-cd environment")
331			// NOTE: we only apply those runtime environment labels for CI/CD runs to ensure other assets from the
332			// inventory are not touched, we may consider to add the data to the flagAsset
333			if runtimeEnv != nil {
334				runtimeLabels := runtimeEnv.Labels()
335				conf.Inventory.ApplyLabels(runtimeLabels)
336			}
337			conf.Inventory.ApplyCategory(inventory.AssetCategory_CATEGORY_CICD)
338		}
339	
340		serviceAccount := opts.GetServiceCredential()
341	
342		// NOTE: even if we have incognito, we want to set the upstream config. Otherwise we would not be able to
343		// use the policies that are defined in Mondoo Platform
344		if serviceAccount != nil {
345			log.Info().Msg("using service account credentials")
346	
347			spaceMrn := opts.GetParentMrn()
348			if spaceMrn == "" {
349				log.Info().Msgf("spaceMrn is empty, using serviceAccount.ScopeMrn: %s", serviceAccount.ScopeMrn)
350				spaceMrn = serviceAccount.ScopeMrn
351			}
352	
353			conf.runtime.UpstreamConfig = &upstream.UpstreamConfig{
354				SpaceMrn:    spaceMrn,
355				ApiEndpoint: opts.UpstreamApiEndpoint(),
356				ApiProxy:    opts.APIProxy,
357				Incognito:   conf.IsIncognito,
358				Creds:       serviceAccount,
359			}
360			providers.DefaultRuntime().UpstreamConfig = conf.runtime.UpstreamConfig
361		} else {
362			// only warn users that we switch to incognito if we aren't already in incognito
363			if !conf.IsIncognito {
364				log.Warn().Msg("No credentials provided. Switching to --incognito mode.")
365			}
366			conf.IsIncognito = true
367		}
368	
369		if len(conf.PolicyPaths) > 0 && !conf.IsIncognito {
370			log.Warn().Msg("Scanning with local bundles will switch into --incognito mode by default. Your results will not be sent upstream.")
371			conf.IsIncognito = true
372		}
373	
374		// print headline when its not printed to yaml
375		if output == "" {
376			fmt.Fprintln(os.Stdout, theme.DefaultTheme.Landing)
377		}
378	
379		return &conf, nil
380	}
