382	func (c *scanConfig) loadPolicies(ctx context.Context) error {
383		if c.IsIncognito {
384			if len(c.PolicyPaths) == 0 {
385				return nil
386			}
387	
388			bundleLoader := policy.DefaultBundleLoader()
389			bundle, err := bundleLoader.BundleFromPaths(c.PolicyPaths...)
390			if err != nil {
391				return err
392			}
393	
394			// ensure all required providers are installed before we try to compile the bundle
395			if bundle.HasRequirements() {
396				autoUpdate := true
397				if viper.IsSet("auto-update") {
398					autoUpdate = viper.GetBool("auto-update")
399				}
400				if err := bundle.EnsureRequirements(autoUpdate); err != nil {
401					return errors.Wrap(err, "failed to ensure policy requirements")
402				}
403			}
404	
405			// prepare the bundle for compilation
406			bundle.Prepare()
407			conf := mqlc.NewConfig(c.runtime.Schema(), mql.DefaultFeatures)
408	
409			_, err = bundle.CompileExt(ctx, policy.BundleCompileConf{
410				CompilerConfig: conf,
411				// We don't care about failing queries for local runs. We may only
412				// process a subset of all the queries in the bundle. When we receive
413				// things from the server, upstream can filter things for us. But running
414				// them locally requires us to do it in here.
415				RemoveFailing: true,
416			})
417			if err != nil {
418				return errors.Wrap(err, "failed to compile bundle")
419			}
420	
421			c.Bundle = bundle
422			return nil
423		}
424	
425		return nil
426	}
