336		// if we had asset errors we want to place them into the reporter
337		for i := range discoveredAssets.Errors {
338			reporter.AddScanError(discoveredAssets.Errors[i].Asset, discoveredAssets.Errors[i].Err)
339		}
340	
341		// For each discovered asset, we initialize a new runtime and connect to it.
342		// Within this process, we set up a catch-all deferred function, that shuts
343		// down all runtimes, in case we exit early.
344		defer func() {
345			for _, asset := range discoveredAssets.Assets {
346				// we can call close multiple times and it will only execute once
347				if asset.Runtime != nil {
