361	
362		// start the progress bar
363		scanGroups := sync.WaitGroup{}
364		scanGroups.Add(1)
365		go func() {
366			defer scanGroups.Done()
367			defer health.ReportPanic("cnspec", cnspec.Version, cnspec.Build)
368	
369			if err := multiprogress.Open(); err != nil {
370				log.Error().Err(err).Msg("failed to open progress bar")
371			}
372		}()
373		// Make sure the progress bar is closed when we exit early. Calling this multiple times
374		// is safe
375		defer multiprogress.Close()
