399				assetsToSync := make([]*inventory.Asset, 0, len(batch))
400				for i := range batch {
401					// If discovery has been skipped, then we don't sync that asset just yet. We will do that during the scan
402					if batch[i].Asset.Connections[0].DelayDiscovery {
403						continue
404					}
405					assetsToSync = append(assetsToSync, batch[i].Asset)
406				}
407				log.Debug().Int("assets", len(assetsToSync)).Msg("synchronizing assets upstream")
