414				}
415				log.Debug().Int("assets", len(resp.Details)).Msg("got assets details")
416				platformAssetMapping := make(map[string]*policy.SynchronizeAssetsRespAssetDetail)
417				for i := range resp.Details {
418					log.Debug().Str("platform-mrn", resp.Details[i].PlatformMrn).Str("asset", resp.Details[i].AssetMrn).Msg("asset mapping")
419					platformAssetMapping[resp.Details[i].PlatformMrn] = resp.Details[i]
420				}
421	
422				// attach the asset details to the assets list
423				for i := range batch {
424					cur := batch[i]
425					asset := cur.Asset
426					log.Debug().Str("asset", asset.Name).Strs("platform-ids", asset.PlatformIds).Msg("update asset")
427	
428					for _, platformMrn := range asset.PlatformIds {
429						if details, ok := platformAssetMapping[platformMrn]; ok {
430							asset.Mrn = details.AssetMrn
431							asset.Url = details.Url
432							asset.Labels["mondoo.com/project-id"] = details.ProjectId
433	
434							if asset.Annotations == nil {
435								asset.Annotations = make(map[string]string)
436							}
437							for k, v := range details.Annotations {
438								if _, ok := asset.Annotations[k]; !ok {
439									asset.Annotations[k] = v
440								}
441							}
442	
443							err = cur.Runtime.SetRecording(s.recording)
444							if err != nil {
445								// we do not want to stop the scan if we cannot set the recording
446								log.Error().Err(err).Msg("could not set recording")
447								break
448							}
449							cur.Runtime.AssetUpdated(asset)
450							break
451						}
452					}
453	
454				}
455			} else {
456				// ensure we have non-empty asset MRNs
457				for i := range batch {
458					asset := batch[i].Asset
459					if asset.Mrn == "" {
460						randID := "//" + policy.POLICY_SERVICE_NAME + "/" + policy.MRN_RESOURCE_ASSET + "/" + ksuid.New().String()
461						x, err := mrn.NewMRN(randID)
462						if err != nil {
463							return nil, multierr.Wrap(err, "failed to generate a random asset MRN")
464						}
465						asset.Mrn = x.String()
466						batch[i].Runtime.AssetUpdated(asset)
