486						return
487					}
488	
489					serviceAccount := opts.GetServiceCredential()
490					if serviceAccount == nil {
491						log.Error().Msg("no service account configured")
492						return
493					}
494	
495					tags := map[string]string{
496						"spaceMrn": spaceMrn,
497					}
498					if len(batch) > 0 {
499						tags["assetMrn"] = batch[0].Asset.Mrn
500						tags["assetName"] = batch[0].Asset.Name
501						tags["platformIDs"] = strings.Join(batch[0].Asset.PlatformIds, ",")
502						tags["assetPlatform"] = batch[0].Asset.Platform.Name
503						tags["assetPlatformVersion"] = batch[0].Asset.Platform.Version
504					}
505	
506					// 2. create local support bundle
507					event := &health.SendErrorReq{
508						ServiceAccountMrn: opts.ServiceAccountMrn,
509						AgentMrn:          opts.AgentMrn,
510						Product: &health.ProductInfo{
511							Name:    product,
512							Version: version,
513							Build:   build,
514						},
515						Error: &health.ErrorInfo{
516							Message:    "panic: " + fmt.Sprintf("%v -- %v", r, tags),
517							Stacktrace: string(stacktrace),
518						},
519					}
520	
521					// 3. send error to mondoo platform
522					sendErrorToMondooPlatform(serviceAccount, event)
523	
524					log.Info().Msg("reported panic to Mondoo Platform")
525				})
526	
527				// Register all tasks in the batch before scanning so the TODO list
528				// knows the full set and does not quit after the first completion.
529				// Skip assets with DelayDiscovery since their platform IDs may
530				// change during discovery; they are registered after discovery.
531				for i := range batch {
532					a := batch[i].Asset
533					if len(a.PlatformIds) > 0 && !a.Connections[0].DelayDiscovery {
534						multiprogress.AddTask(a.PlatformIds[0], a)
535					}
536				}
537	
538				for i := range batch {
539					asset := batch[i].Asset
540					runtime := batch[i].Runtime
541	
542					if err := runtime.EnsureProvidersConnected(); err != nil {
543						log.Error().Err(err).Msg("could not connect to providers")
544					}
545	
546					log.Debug().Interface("platform", asset.Platform).Str("name", asset.Name).Msg("start scan")
547	
548					// Make sure the context has not been canceled in the meantime. Note that this approach works only for single threaded execution. If we have more than 1 thread calling this function,
549					// we need to solve this at a different level.
550					select {
551					case <-ctx.Done():
552						log.Warn().Msg("request context has been canceled")
553						// When we scan concurrently, we need to call Errored(asset.Mrn) status for this asset
554						multiprogress.Close()
555						return
556					default:
557					}
558	
559					if asset.Connections[0].DelayDiscovery {
560						discoveredAsset, err := handleDelayedDiscovery(ctx, asset, runtime, services, spaceMrn)
561						if err != nil {
562							reporter.AddScanError(asset, err)
563							if len(asset.PlatformIds) > 0 {
564								multiprogress.Errored(asset.PlatformIds[0])
565							}
566							continue
567						}
568						asset = discoveredAsset
569						// Re-register with the discovered asset's platform ID if it changed
570						multiprogress.AddTask(asset.PlatformIds[0], asset)
571					}
572	
573					if len(asset.PlatformIds) == 0 {
574						log.Warn().Str("name", asset.Name).Msg("asset has no platform IDs, skipping")
575						continue
576					}
577	
578					p := &progress.MultiProgressAdapter{Key: asset.PlatformIds[0], Multi: multiprogress}
579					s.RunAssetJob(&AssetJob{
580						DoRecord:         job.DoRecord,
581						UpstreamConfig:   upstream,
582						Asset:            asset,
583						Bundle:           job.Bundle,
584						Props:            job.Props,
585						PolicyFilters:    preprocessPolicyFilters(job.PolicyFilters),
586						Ctx:              ctx,
587						Reporter:         reporter,
588						ProgressReporter: p,
589						runtime:          runtime,
590					})
591	
592					// Report any recovered provider panics to the Mondoo Platform.
593					for _, critErr := range runtime.CriticalErrors() {
594						tags := map[string]string{
595							"assetMrn":  asset.Mrn,
596							"assetName": asset.Name,
597						}
598						if len(asset.PlatformIds) > 0 {
599							tags["platformIDs"] = strings.Join(asset.PlatformIds, ",")
600						}
601						if asset.Platform != nil {
602							tags["assetPlatform"] = asset.Platform.Name
603							tags["assetPlatformVersion"] = asset.Platform.Version
604						}
605						health.ReportError("cnspec", cnspec.Version, cnspec.Build, critErr.Error(), health.WithTags(tags))
606					}
607	
608					// shut down all ephemeral runtimes
609					runtime.Close()
610				}
611			}()
612			wg.Wait()
613		}
614		scanGroups.Wait() // wait for all scans to complete
615		return reporter.Reports(), nil
616	}
