 38	type BundleResolver interface {
 39		Load(ctx context.Context, path string) (*Bundle, error)
 40		IsApplicable(path string) bool
 41	}
 42	
 43	type BundleLoader struct {
 44		resolvers []BundleResolver
 45	}
 46	
 47	func NewBundleLoader(resolvers ...BundleResolver) *BundleLoader {
 48		return &BundleLoader{resolvers: resolvers}
 49	}
 50	
 51	func DefaultBundleLoader() *BundleLoader {
 52		return NewBundleLoader(defaultS3BundleResolver(), defaultHTTPBundleResolver(), defaultFileBundleResolver())
 53	}
 54	
 55	func (l *BundleLoader) getResolver(path string) (BundleResolver, error) {
 56		for _, resolver := range l.resolvers {
 57			if resolver.IsApplicable(path) {
 58				return resolver, nil
 59			}
 60		}
 61		return nil, fmt.Errorf("no resolver found for path '%s'", path)
 62	}
 63	
 64	// Deprecated: Use BundleLoader.BundleFromPaths instead
 65	func BundleFromPaths(paths ...string) (*Bundle, error) {
 66		defaultLoader := DefaultBundleLoader()
 67		return defaultLoader.BundleFromPaths(paths...)
 68	}
 69	
 70	// iterates through all the resolvers until it finds an applicable one and then uses that to load the bundle
 71	// from the provided path
 72	func (l *BundleLoader) BundleFromPaths(paths ...string) (*Bundle, error) {
 73		ctx := context.Background()
 74		aggregatedBundle := &Bundle{}
 75		for _, path := range paths {
 76			resolver, err := l.getResolver(path)
 77			if err != nil {
 78				return nil, err
 79			}
 80			bundle, err := resolver.Load(ctx, path)
 81			if err != nil {
 82				log.Error().Err(err).Msg("could not resolve bundle files")
 83				return nil, err
 84			}
 85			aggregatedBundle = Merge(aggregatedBundle, bundle)
 86		}
 87	
 88		logger.DebugDumpYAML("resolved_mql_bundle.mql", aggregatedBundle)
 89		return aggregatedBundle, nil
 90	}
