110	// Merge combines two PolicyBundle and merges the data additive into one
111	// single PolicyBundle structure
112	func Merge(a *Bundle, b *Bundle) *Bundle {
113		res := &Bundle{}
114	
115		res.OwnerMrn = a.OwnerMrn
116		if b.OwnerMrn != "" {
117			res.OwnerMrn = b.OwnerMrn
118		}
119	
120		// merge in a
121		res.Policies = append(res.Policies, a.Policies...)
122		res.Packs = append(res.Packs, a.Packs...)
123		res.Props = append(res.Props, a.Props...)
124		res.Queries = append(res.Queries, a.Queries...)
125		res.Frameworks = append(res.Frameworks, a.Frameworks...)
126		res.FrameworkMaps = append(res.FrameworkMaps, a.FrameworkMaps...)
127		res.MigrationGroups = append(res.MigrationGroups, a.MigrationGroups...)
128	
129		// merge in b
130		res.Policies = append(res.Policies, b.Policies...)
131		res.Packs = append(res.Packs, b.Packs...)
132		res.Props = append(res.Props, b.Props...)
133		res.Queries = append(res.Queries, b.Queries...)
134		res.Frameworks = append(res.Frameworks, b.Frameworks...)
135		res.FrameworkMaps = append(res.FrameworkMaps, b.FrameworkMaps...)
136		res.MigrationGroups = append(res.MigrationGroups, b.MigrationGroups...)
137	
138		return res
139	}
