160	// and turns them into policies for execution by cnspec.
161	func (p *Bundle) ConvertQuerypacks() {
162		for i := range p.Packs {
163			pack := p.Packs[i]
164	
165			policy := Policy{
166				Mrn:      pack.Mrn,
167				Uid:      pack.Uid,
168				Name:     pack.Name,
169				Version:  pack.Version,
170				License:  pack.License,
171				OwnerMrn: pack.OwnerMrn,
172				Docs:     convertQueryPackDocs(pack.Docs),
173				Summary:  pack.Summary,
174				Authors:  pack.Authors,
175				Created:  pack.Created,
176				Modified: pack.Modified,
177				Tags:     pack.Tags,
178				Props:    pack.Props,
179				Require:  pack.Require,
180				Groups:   convertQueryPackGroups(pack),
181				// we need this to indicate that the policy was converted from a querypack
182				ScoringSystem: ScoringSystem_DATA_ONLY,
183			}
184			p.Policies = append(p.Policies, &policy)
185		}
