209	func convertQueryPackGroups(p *QueryPack) []*PolicyGroup {
210		var res []*PolicyGroup
211	
212		if len(p.Queries) > 0 {
213			// any builtin queries need to be put into a group for policies
214			res = append(res, &PolicyGroup{
215				Queries: p.Queries,
216				Type:    GroupType_CHAPTER,
217				Uid:     "default-queries",
218				Title:   "Default Queries",
219				Filters: p.Filters,
220			})
221		}
222		for i := range p.Groups {
223			g := p.Groups[i]
224			res = append(res, &PolicyGroup{
225				Queries:  g.Queries,
226				Type:     GroupType_CHAPTER,
227				Uid:      g.Uid,
228				Filters:  g.Filters,
229				Created:  g.Created,
230				Modified: g.Modified,
231				Title:    g.Title,
232			})
233		}
234	
235		return res
236	}
