 72	
 73	// NewSqliteScanDataStore creates a new SQLite-based scan data store for writing
 74	func NewSqliteScanDataStore(filePath string, assetMrn string) (*SqliteScanDataStore, error) {
 75		sqlDB, err := sql.Open("sqlite", filePath)
 76		if err != nil {
 77			return nil, fmt.Errorf("failed to open sqlite file: %w", err)
 78		}
 79	
 80		queries, err := sqlc.Prepare(context.Background(), sqlDB)
 81		if err != nil {
 82			sqlDB.Close()
 83			return nil, fmt.Errorf("failed to prepare queries: %w", err)
 84		}
 85	
 86		store := &SqliteScanDataStore{
 87			sqlDB:    sqlDB,
 88			queries:  queries,
 89			assetMrn: assetMrn,
 90			filePath: filePath,
 91			readOnly: false,
 92		}
 93	
 94		if err := store.initializeDatabase(); err != nil {
 95			sqlDB.Close()
 96			return nil, fmt.Errorf("failed to initialize database: %w", err)
 97		}
 98	
 99		return store, nil
100	}
101	
102	// NewSqliteScanDataStoreReader creates a new SQLite-based scan data store for reading
103	func NewSqliteScanDataStoreReader(filePath string) (*SqliteScanDataStore, error) {
104		sqlDB, err := sql.Open("sqlite", filePath+"?mode=ro")
105		if err != nil {
106			return nil, fmt.Errorf("failed to open sqlite file: %w", err)
107		}
108	
109		queries := sqlc.New(sqlDB)
110	
111		return &SqliteScanDataStore{
112			sqlDB:    sqlDB,
113			queries:  queries,
114			filePath: filePath,
115			readOnly: true,
116		}, nil
117	}
