119	// initializeDatabase sets up the schema and metadata for write mode
120	func (s *SqliteScanDataStore) initializeDatabase() error {
121		if s.readOnly {
122			return fmt.Errorf("cannot initialize database in read-only mode")
123		}
124	
125		// Execute the embedded schema
126		if _, err := s.sqlDB.Exec(uploadSchema); err != nil {
127			return fmt.Errorf("failed to create schema: %w", err)
128		}
129	
130		// Insert metadata
131		if err := s.insertMetadata(); err != nil {
132			return fmt.Errorf("failed to insert metadata: %w", err)
133		}
134	
135		return nil
136	}
137	
138	// insertMetadata adds metadata about the upload
139	func (s *SqliteScanDataStore) insertMetadata() error {
140		ctx := context.Background()
141		metadata := map[string]string{
142			"schema_version": SchemaVersion,
143			"asset_mrn":      s.assetMrn,
144			"created_at":     time.Now().Format(time.RFC3339),
145			"client_version": cnspec.GetVersion(),
146			"client_build":   cnspec.GetBuild(),
147		}
148	
149		for key, value := range metadata {
150			if err := s.queries.InsertMetadata(ctx, sqlc.InsertMetadataParams{
151				Key:   key,
152				Value: value,
153			}); err != nil {
154				return fmt.Errorf("failed to insert metadata %s: %w", key, err)
155			}
156		}
157	
158		return nil
159	}
160	
161	// WriteScores writes multiple scores efficiently
162	func (s *SqliteScanDataStore) WriteScores(ctx context.Context, scores []*policy.Score) error {
163		if s.readOnly {
164			return fmt.Errorf("cannot write scores in read-only mode")
165		}
166	
167		for _, score := range scores {
168			if err := s.writeScore(ctx, score); err != nil {
169				return fmt.Errorf("failed to write score %s: %w", score.QrId, err)
170			}
171		}
172		return nil
173	}
