175	// WriteData writes multiple data results
176	func (s *SqliteScanDataStore) WriteData(ctx context.Context, data []*llx.Result) error {
177		if s.readOnly {
178			return fmt.Errorf("cannot write data in read-only mode")
179		}
180	
181		for _, result := range data {
182			codeId := result.CodeId
183			resultData, err := proto.Marshal(result)
184			if err != nil {
185				return fmt.Errorf("failed to marshal result %s: %w", codeId, err)
186			}
187	
188			if err := s.queries.InsertData(ctx, sqlc.InsertDataParams{
189				CodeID: codeId,
190				Data:   resultData,
191			}); err != nil {
192				return fmt.Errorf("failed to write data %s: %w", codeId, err)
193			}
194		}
195	
196		return nil
197	}
