199	func (s *SqliteScanDataStore) WriteResource(ctx context.Context, resource *llx.ResourceRecording) error {
200		if s.readOnly {
201			return fmt.Errorf("cannot write resource in read-only mode")
202		}
203	
204		resourceData, err := proto.Marshal(resource)
205		if err != nil {
206			return fmt.Errorf("failed to marshal resource %s/%s: %w", resource.Resource, resource.Id, err)
207		}
208	
209		if err := s.queries.InsertResource(ctx, sqlc.InsertResourceParams{
210			Name: resource.Resource,
211			ID:   resource.Id,
212			Data: resourceData,
213		}); err != nil {
214			return fmt.Errorf("failed to write resource %s/%s: %w", resource.Resource, resource.Id, err)
215		}
