207	func (e *Executor) AddCode(code string, props mqlc.PropsHandler) (*llx.CodeBundle, error) {
208		codeBundle, err := e.Compile(code, props)
209		if err != nil {
210			return nil, err
211		}
212		if err := e.AddCodeBundle(codeBundle, props); err != nil {
213			return nil, err
214		}
215		return codeBundle, nil
216	}
217	
218	// AddCode to the executor
219	func (e *Executor) AddCodeBundle(codeBundle *llx.CodeBundle, props mqlc.PropsHandler) error {
220		codeID := codeBundle.CodeV2.Id
221	
222		if props == nil {
223			props = mqlc.EmptyPropsHandler
224		}
225	
226		org, ok := e.RunningCode.Load(codeID)
227		if ok && org.CodeV2.Id == codeBundle.CodeV2.Id {
228			return nil
229		}
230	
231		if ok {
232			log.Warn().Str("codeID", codeID).Msg("executor> content for codeID doesn't match code content")
233			e.RemoveCode(codeID, codeBundle.Source)
234		}
235	
236		e.RunningCode.Store(codeID, codeBundle)
237		e.bundleErrors.ClearGroup(codeID)
238		if len(codeBundle.CodeV2.Entrypoints())+len(codeBundle.CodeV2.Datapoints()) == 0 {
239			e.updateBundle(codeID)
240		} else {
241			runSafe, runerr := isRunSafe(codeBundle)
242			e.incrementWaitGroup(codeBundle)
243	
244			// we extract a closure-based copy of the waitgroup. if we run into timeouts
245			// the llx callback may happen after the waitgroup has been decommissioned
246			// in that case due to the closure it will reference the old waitgroup
247			waitGroup := e.waitGroup
248			results := e.Results
249			scoreResults := e.ScoreResults
250	
251			executor, err := llx.NewExecutorV2(codeBundle.CodeV2, e.runtime, props.All(), func(res *llx.RawResult) {
252				e.onResult(res, waitGroup, results, scoreResults)
253			})
254			if err != nil {
255				return err
256			}
257	
258			if !runSafe {
259				executor.NoRun(runerr)
260			} else {
261				err = executor.Run()
262			}
263	
264			if err != nil {
265				return err
266			}
267			e.executors[codeID] = executor
268		}
269		return nil
270	}
271	
272	func isRunSafe(codeBundle *llx.CodeBundle) (bool, error) {
273		if codeBundle.MinMondooVersion != "" {
274			requiredVer := codeBundle.MinMondooVersion
275			currentVer := cnspec.GetCoreVersion()
276			if currentVer == "unstable" {
277				// Probably running locally since ldflags didn't config version
278				// Entering yolo mode (its probably safe!)
279				return true, nil
280			}

