 21	func WithServices(ctx context.Context, runtime llx.Runtime, assetMrn string, upstreamClient *upstream.UpstreamClient, f func(*policy.LocalServices) error) error {
 22		err := withSqliteDataStore(assetMrn, func(scanDataStore scandb.ScanDataStore) error {
 23			_, ls, err := inmemory.NewServices(runtime, inmemory.WithDataWriter(scandb.NewScanDataStoreWrapper(scanDataStore, assetMrn)))
 24	
 25			if err != nil {
 26				return err
 27			}
 28	
 29			var upstream *policy.Services
 30			if upstreamClient != nil {
 31				var err error
 32				upstream, err = policy.NewRemoteServices(upstreamClient.ApiEndpoint, upstreamClient.Plugins, upstreamClient.HttpClient)
 33				if err != nil {
 34					return err
 35				}
 36				upstream.PolicyResolver = &policy.NoStoreResults{
 37					PolicyResolver: upstream.PolicyResolver,
 38				}
 39			}
 40	
 41			ls.Upstream = upstream
 42			if err := f(ls); err != nil {
 43				return err
 44			}
 45	
 46			if upstream != nil {
 47				scanDataPath, err := scanDataStore.Finalize()
 48				if err != nil {
 49					return err
 50				}
 51	
 52				return uploadScanDataStore(ctx, upstream, assetMrn, scanDataPath)
 53			}
 54	
 55			return nil
 56		})
 57		if err != nil {
 58			return err
 59		}
 60	
 61		return nil
 62	}
 63	
 64	func withSqliteDataStore(assetMrn string, f func(scanDataStore scandb.ScanDataStore) error) error {
 65		// create a temporary file for the scan data store
 66		tmpFile, err := os.CreateTemp("", "cnspec-scan-*.db")
 67		if err != nil {
 68			log.Error().Err(err).Msg("failed to create temporary file for scan data store")
 69			return err
 70		}
 71		tmpFile.Close() // nolint: errcheck
 72		defer func() {
 73			if err := os.Remove(tmpFile.Name()); err != nil {
 74				log.Warn().Err(err).Msg("failed to remove temporary scan data store file")
 75			}
 76		}()
 77	
 78		scanDataStore, err := scandb.NewSqliteScanDataStore(tmpFile.Name(), assetMrn)
 79		if err != nil {
 80			log.Error().Err(err).Msg("failed to create scan data store")
 81			return err
 82		}
 83		defer scanDataStore.Close()
 84	
 85		return f(scanDataStore)
 86	}
 87	
 88	func uploadScanDataStore(ctx context.Context, services *policy.Services, assetMrn string, scanDataPath string) error {
 89		urlResp, err := services.GetUploadURL(ctx, &policy.GetUploadURLReq{
 90			Kind:     policy.UploadURLKind_UPLOAD_URL_KIND_SCAN_DATABASE_V0,
 91			ScopeMrn: assetMrn,
 92		})
 93		if err != nil {
 94			return err
 95		}
 96	
 97		uploadUrl := urlResp.UploadUrl
 98		if uploadUrl == nil {
 99			return errors.New("no upload URL for scan data store")
100		}
101	
102		headers := uploadUrl.Headers
103		url := uploadUrl.Url
104	
105		// Open the scan database file
106		file, err := os.Open(scanDataPath)
107		if err != nil {
108			return err
109		}
110		defer file.Close()
111	
112		// Create HTTP request for upload
113		req, err := http.NewRequestWithContext(ctx, "PUT", url, file)
114		if err != nil {
115			return err
116		}
117	
118		// Set required headers from the signed URL
119		for key, value := range headers {
120			req.Header.Set(key, value)
121		}
122	
123		// Add file size header
124		fileInfo, err := file.Stat()
125		if err != nil {
126			return err
127		}
128		req.ContentLength = fileInfo.Size()
129		req.Header.Set("Content-Type", "application/octet-stream")
130	
131		// Perform the upload
132		client := &http.Client{}
133		resp, err := client.Do(req)
134		if err != nil {
135			return err
136		}
137		defer resp.Body.Close()
138	
139		if resp.StatusCode != http.StatusOK && resp.StatusCode != http.StatusCreated {
140			return fmt.Errorf("upload failed with status %d", resp.StatusCode)
141		}
142	
143		// Confirm the upload
144		_, err = services.ReportUploadCompleted(ctx, &policy.ReportUploadCompletedReq{
145			UploadSessionId: urlResp.UploadSessionId,
146			ScopeMrn:        assetMrn,
147		})
148		if err != nil {
149			return err
150		}
151	
152		log.Info().Str("session", urlResp.UploadSessionId).Msg("successfully uploaded scan data store")
153		return nil
154	}

