 97	// maxParallelConnHTTPTransport restricts the parallel connections upstream.
 98	type maxParallelConnHTTPTransport struct {
 99		transport     http.RoundTripper
100		parallelConns *semaphore.Weighted
101	}
102	
103	func (t *maxParallelConnHTTPTransport) RoundTrip(r *http.Request) (*http.Response, error) {
104		err := t.parallelConns.Acquire(r.Context(), 1)
105		if err != nil {
106			return nil, err
107		}
108		defer t.parallelConns.Release(1)
109		return t.transport.RoundTrip(r)
110	}
