112	func newMaxParallelConnTransport(transport http.RoundTripper, parallel int64) *maxParallelConnHTTPTransport {
113		return &maxParallelConnHTTPTransport{
114			transport:     transport,
115			parallelConns: semaphore.NewWeighted(parallel),
116		}
117	}
