 13	func (r *Report) RawResults() map[string]*llx.RawResult {
 14		results := map[string]*llx.RawResult{}
 15	
 16		// covert all proto results to raw results
 17		for k := range r.Data {
 18			result := r.Data[k]
 19			results[k] = result.RawResultV2()
 20		}
 21	
 22		return results
