 25	// Stats computes the stats for this report
 26	func (r *Report) ComputeStats(resolved *ResolvedPolicy) {
 27		res := Stats{
 28			Failed: &ScoreDistribution{},
 29			Passed: &ScoreDistribution{},
 30			Errors: &ScoreDistribution{},
 31		}
 32	
 33		queries := resolved.CollectorJob.ReportingQueries
 34	
 35		for id, score := range r.Scores {
 36			if _, ok := queries[id]; ok {
 37				res.Add(score)
 38			}
 39		}
 40	
 41		r.Stats = &res
 42	}
 43	func (s *Stats) Add(score *Score) {
 44		s.AddCount(score, 1)
 45	}
 46	
 47	func (s *Stats) AddCount(score *Score, count uint32) {
 48		s.Total += count
 49		switch score.Type {
 50		case ScoreType_Unknown:
 51			s.Unknown += count
 52		case ScoreType_Result:
 53			if score.Value < 100 {
 54				s.Failed.AddCount(score, count)
 55	
 56				if score.Value < s.Worst {
 57					s.Worst = score.Value
 58				}
 59	
 60			} else {
 61				s.Passed.AddCount(score, count)
 62			}
 63		case ScoreType_Error:
 64			s.Errors.AddCount(score, count)
 65		case ScoreType_Skip:
 66			s.Skipped += count
 67		case ScoreType_Unscored:
 68			s.Unknown += count
 69		default:
 70			log.Warn().Uint32("type", score.Type).Str("id", score.QrId).Msg("ran into unknown score type")
 71		}
 72	}
 73	
 74	// this function also handles nil scores and updates the score distribution accordingly
 75	func (sd *ScoreDistribution) Add(score *Score) {
 76		sd.AddCount(score, 1)
 77	}
 78	
 79	func (sd *ScoreDistribution) AddCount(score *Score, count uint32) {
 80		sd.AddRatingCount(score.Rating(), count)
 81	}
 82	
 83	// this function also handles nil scores and updates the score distribution accordingly
 84	func (sd *ScoreDistribution) Remove(score *Score) {
 85		sd.RemoveRating(score.Rating())
 86	}
 87	
 88	func (sd *ScoreDistribution) AddRating(scoreRating ScoreRating) {
 89		sd.AddRatingCount(scoreRating, 1)
 90	}
 91	
 92	func (sd *ScoreDistribution) AddRatingCount(scoreRating ScoreRating, count uint32) {
 93		sd.Total += count
 94		switch scoreRating {
 95		case ScoreRating_aPlus, ScoreRating_a, ScoreRating_aMinus:
 96			sd.A += count
 97		case ScoreRating_bPlus, ScoreRating_b, ScoreRating_bMinus:
 98			sd.B += count
 99		case ScoreRating_cPlus, ScoreRating_c, ScoreRating_cMinus:
100			sd.C += count
101		case ScoreRating_dPlus, ScoreRating_d, ScoreRating_dMinus:
102			sd.D += count
103		case ScoreRating_failed:
104			sd.F += count
105		case ScoreRating_error:
106			sd.Error += count
