30	func defaultHTTPBundleResolver() *httpBundleResolver {
31		return &httpBundleResolver{}
32	}
33	
34	// NewHTTPBundleResolver creates an HTTP bundle resolver with the provided HTTP
35	// client. This is useful for testing with httptest.NewServer.
36	func NewHTTPBundleResolver(client HTTPDoer) *httpBundleResolver {
37		return &httpBundleResolver{client: client}
38	}
