40	func (r *httpBundleResolver) IsApplicable(path string) bool {
41		return strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://")
42	}
43	
44	func (r *httpBundleResolver) Load(ctx context.Context, path string) (*Bundle, error) {
45		client := r.client
46		if client == nil {
47			client = &http.Client{
48				Timeout: 30 * time.Second,
49			}
50		}
51	
52		req, err := http.NewRequestWithContext(ctx, "GET", path, nil)
53		if err != nil {
54			return nil, errors.Wrap(err, "failed to create request for policy bundle")
55		}
56	
57		req.Header.Set("User-Agent", "Mozilla/5.0 (compatible; cnspec/"+cnspec.Version+"; +http://www.mondoo.com)")
58	
59		resp, err := client.Do(req)
60		if err != nil {
61			return nil, errors.Wrap(err, "failed to fetch policy bundle from "+path)
62		}
63		defer resp.Body.Close()
64	
65		if resp.StatusCode != http.StatusOK {
66			return nil, httpError(path, resp.StatusCode, resp.Status)
67		}
68	
69		data, err := io.ReadAll(io.LimitReader(resp.Body, maxBundleSize))
70		if err != nil {
71			return nil, errors.Wrap(err, "failed to read policy bundle response from "+path)
72		}
73	
74		log.Debug().Str("url", path).Msg("http>loaded bundle file from URL")
75		return BundleFromYAML(data)
76	}
77	
78	func httpError(url string, statusCode int, status string) error {
79		switch statusCode {
80		case http.StatusBadRequest:
81			return errors.Newf("failed to fetch policy bundle from %s: the server indicated the request was malformed (HTTP 400 Bad Request)", url)
82		case http.StatusForbidden:
83			return errors.Newf("failed to fetch policy bundle from %s: access denied, ensure the URL is correct and publicly accessible or that valid credentials are provided (HTTP 403 Forbidden)", url)
84		case http.StatusNotFound:
85			return errors.Newf("failed to fetch policy bundle from %s: resource not found (HTTP 404 Not Found)", url)
86		default:
87			return errors.Newf("failed to fetch policy bundle from %s: %s", url, status)
88		}
89	}

