33	func (r *s3BundleResolver) Load(ctx context.Context, path string) (*Bundle, error) {
34		// if we have no explicitly provided s3 client, we need to create one. we can optimize this later on by ensuring we require a client
35		// when creating the s3 bundle resolver
36		if r.s3Client == nil {
37			cfg, err := awsconfigv2.LoadDefaultConfig(ctx)
38			if err != nil {
39				return nil, err
40			}
41			r.s3Client = s3.NewFromConfig(cfg)
42		}
43		trimmed := strings.TrimPrefix(path, "s3://")
44		if ok, bucket, key := isS3Key(trimmed); ok {
45			return r.fetchBundleFromS3(ctx, bucket, key)
46		}
47	
48		// else we're looking at a bucket so we need to iterate over all the files inside
49		files, err := r.s3Client.ListObjects(ctx, &s3.ListObjectsInput{Bucket: &trimmed})
50		if err != nil {
51			return nil, err
52		}
53		mergedBundle := &Bundle{}
54		resolvedNames := []string{}
55		for _, file := range files.Contents {
56			key := *file.Key
57			if strings.HasSuffix(key, ".mql.yaml") || strings.HasSuffix(key, ".mql.yml") {
58				resolvedNames = append(resolvedNames, key)
59			}
60		}
61		for _, file := range resolvedNames {
62			bundle, err := r.fetchBundleFromS3(ctx, trimmed, file)
63			if err != nil {
64				return nil, err
65			}
66			mergedBundle = Merge(mergedBundle, bundle)
67		}
68		return mergedBundle, nil
69	}
