75	// basic check that validates if the provided path is a s3 key. it returns the bucket and the key that can be used to fetch the object
76	// an s3 key is defined as a path that contains more than one slash, e.g. my-bucket/my-key
77	func isS3Key(path string) (bool, string, string) {
78		parts := strings.Split(path, "/")
79		if len(parts) > 1 {
80			return true, parts[0], strings.Join(parts[1:], "/")
81		}
82		return false, "", ""
83	}
