85	func (r *s3BundleResolver) fetchBundleFromS3(ctx context.Context, bucket string, key string) (*Bundle, error) {
86		resp, err := r.s3Client.GetObject(ctx, &s3.GetObjectInput{Bucket: &bucket, Key: &key})
87		if err != nil {
88			return nil, err
89		}
90		data, err := io.ReadAll(resp.Body)
91		if err != nil {
92			return nil, err
93		}
94		log.Debug().Str("bucket", bucket).Str("key", key).Msg("s3>loaded bundle file from s3")
95		return BundleFromYAML(data)
