811		dar := &policy.PurgeAssetsRequest{
812			SpaceMrn:        s.upstream.SpaceMrn,
813			ManagedBy:       garbageCollectOpts.ManagedBy,
814			PlatformRuntime: garbageCollectOpts.PlatformRuntime,
815			Labels:          garbageCollectOpts.Labels,
816		}
817	
818		if garbageCollectOpts.OlderThan != "" {
819			timestamp, err := time.Parse(time.RFC3339, garbageCollectOpts.OlderThan)
820			if err != nil {
821				return nil, errors.Wrap(err, "failed converting timestamp from RFC3339 format")
