888	// run() runs a bundle on a single asset. It returns the results of the scan and an error if the scan failed. Even in
889	// case of an error, the results may contain partial results. The error is only returned if the scan failed to run not
890	// when individual policies failed.
891	func (s *localAssetScanner) run() (*AssetReport, error) {
892		if err := s.prepareAsset(); err != nil {
893			return nil, err
894		}
895	
896		resolvedPolicy, err := s.runPolicy()
897		if err != nil {
898			return nil, err
899		}
900	
901		if mql.GetFeatures(s.job.Ctx).IsActive(mql.StoreResourcesData) && resolvedPolicy.HasFeature(policy.ServerFeature_STORE_RESOURCES_DATA) {
902			log.Info().Str("mrn", s.job.Asset.Mrn).Msg("store resources for asset")
903			recording := s.Runtime.Recording()
904			data, ok := recording.GetAssetData(s.job.Asset.Mrn)
905			if !ok {
906				log.Debug().Msg("not storing resource data for this asset, nothing available")
907			} else {
908				_, err = s.services.StoreResults(context.Background(), &policy.StoreResultsReq{
909					AssetMrn:  s.job.Asset.Mrn,
910					Resources: data,
911				})
912				if err != nil {
913					return nil, err
914				}
915			}
916		}
917	
918		ar := &AssetReport{
919			Mrn:            s.job.Asset.Mrn,
920			ResolvedPolicy: resolvedPolicy,
921		}
922	
923		report, err := s.getReport(resolvedPolicy)
924		if err != nil {
925			return ar, err
926		}
927		s.ProgressReporter.Score(report.Score.Rating().Text())
928		if report.Score.Rating().Text() == policy.ScoreRatingTextUnrated {
929			s.ProgressReporter.NotApplicable()
930		} else {
931			s.ProgressReporter.Completed()
932		}
933	
934		log.Debug().Str("asset", s.job.Asset.Mrn).Msg("scan complete")
935		ar.Report = report
936		return ar, nil
937	}
