939	func filterPolicyMrns(b *policy.Bundle, filters []string) []string {
940		if len(filters) == 0 {
941			res := make([]string, len(b.Policies))
942			for i := range b.Policies {
943				res[i] = b.Policies[i].Mrn
944			}
945			return res
946		}
947	
948		var res []string
949		for i := range b.Policies {
950			cur := b.Policies[i]
951			uid, _ := mrn.GetResource(cur.Mrn, policy.MRN_RESOURCE_POLICY)
952			if slices.Contains(filters, uid) || slices.Contains(filters, cur.Mrn) {
953				res = append(res, cur.Mrn)
954			}
955		}
956		return res
957	}
