130	func NewServices(runtime llx.Runtime, opts ...ServiceOpt) (*Db, *policy.LocalServices, error) {
131		var cache kvStore = newKissDb()
132	
133		resolvedPolicyCache := NewResolvedPolicyCache(0)
134	
135		db := &Db{
136			cache:               cache,
137			nowProvider:         time.Now,
138			resolvedPolicyCache: resolvedPolicyCache,
139			writer:              &cacheDataWriter{cache: cache},
140		}
141		for _, opt := range opts {
142			opt(db)
143		}
144	
145		services := policy.NewLocalServices(db, runtime)
146		db.services = services // close the connection between db and services
147	
148		return db, services, nil
149	}
