1023	func (s *localAssetScanner) mapPropOverrides() (*policy.PropsReq, error) {
1024		exposedProps := make(map[string][]string, len(s.job.Props))
1025		for _, pol := range s.job.Bundle.Policies {
1026			for _, prop := range pol.Props {
1027				propUid, err := policy.GetPropName(prop.Mrn)
1028				if err != nil {
1029					return nil, fmt.Errorf("failed to get property name for %s: %w", prop.Mrn, err)
1030				}
1031				exposedProps[propUid] = append(exposedProps[propUid], prop.Mrn)
1032			}
1033		}
1034	
1035		propsReq := policy.PropsReq{
1036			EntityMrn: s.job.Asset.Mrn,
1037			Props:     make([]*policy.Property, 0, len(s.job.Props)),
1038		}
1039		for k, v := range s.job.Props {
1040			newProp := &policy.Property{
1041				Uid: k,
1042				Mql: v,
1043			}
1044			forProps := exposedProps[k]
1045			if len(forProps) == 0 {
1046				continue
1047			}
1048			for _, propMrn := range forProps {
1049				newProp.For = append(newProp.For, &policy.ObjectRef{
1050					Mrn: propMrn,
1051				})
1052			}
1053			if err := newProp.RefreshMRN(s.job.Asset.Mrn); err != nil {
1054				return nil, fmt.Errorf("failed to refresh MRN for property %s: %w", newProp.Mrn, err)
1055			}
1056			propsReq.Props = append(propsReq.Props, newProp)
1057		}
1058	
1059		return &propsReq, nil
1060	}
