1114	func (s *localAssetScanner) runPolicy() (*policy.ResolvedPolicy, error) {
1115		var hub policy.PolicyHub = s.services
1116		var resolver policy.PolicyResolver = s.services
1117	
1118		// If we run in debug mode, download the asset bundle and dump it to disk
1119		if val, ok := os.LookupEnv("DEBUG"); ok && (val == "1" || val == "true") {
1120			log.Debug().Str("asset", s.job.Asset.Mrn).Msg("client> request policies bundle for asset")
1121			assetBundle, err := hub.GetBundle(s.job.Ctx, &policy.Mrn{Mrn: s.job.Asset.Mrn})
1122			if err != nil {
1123				return nil, err
1124			}
1125			log.Debug().Msg("client> got policy bundle")
1126			logger.TraceJSON(assetBundle)
1127			logger.DebugDumpYAML("assetBundle", assetBundle)
1128		}
1129	
1130		rawFilters, err := hub.GetPolicyFilters(s.job.Ctx, &policy.Mrn{Mrn: s.job.Asset.Mrn})
1131		if err != nil {
1132			return nil, err
1133		}
1134		log.Debug().Str("asset", s.job.Asset.Mrn).Msg("client> got policy filters")
1135		logger.TraceJSON(rawFilters)
1136		logger.DebugDumpYAML("policyFilters", rawFilters)
1137	
1138		filters, err := s.UpdateFilters(&policy.Mqueries{Items: rawFilters.Items}, 5*time.Second)
1139		if err != nil {
1140			return nil, err
1141		}
1142		log.Debug().Str("asset", s.job.Asset.Mrn).Msg("client> shell update filters")
1143		logger.DebugJSON(filters)
1144		logger.DebugDumpYAML("assetFilters", filters)
1145	
1146		resolvedPolicy, err := resolver.ResolveAndUpdateJobs(s.job.Ctx, &policy.UpdateAssetJobsReq{
1147			AssetMrn:     s.job.Asset.Mrn,
1148			AssetFilters: filters,
1149		})
1150		if err != nil {
1151			return resolvedPolicy, err
1152		}
1153		log.Debug().Str("asset", s.job.Asset.Mrn).Msg("client> got resolved policy bundle for asset")
1154		logger.DebugDumpJSON("resolvedPolicy", resolvedPolicy)
1155	
1156		features := mql.GetFeatures(s.job.Ctx)
1157		err = executor.ExecuteResolvedPolicy(s.job.Ctx, s.Runtime, resolver, s.job.Asset.Mrn, resolvedPolicy, features, s.ProgressReporter)
1158		if err != nil {
1159			return nil, err
1160		}
1161	
1162		return resolvedPolicy, nil
1163	}
